import{geoOrthographic,geoPath,geoGraticule10,geoDistance}from'd3-geo';import{feature}from'topojson-client';import topo from'../deps/node_modules/world-atlas/land-110m.json';import'./style.css';
const root=document.getElementById('root'),NS='http://www.w3.org/2000/svg';const spots=[{id:'singapore',name:'新加坡',coords:[103.8198,1.3521],job:'整理研究线索',note:'对照原始材料，保留来源与尚未确认的问题。'},{id:'paris',name:'巴黎',coords:[2.3522,48.8566],job:'交接设计评审',note:'将视觉意见整理为可验证的修改清单。'},{id:'sanfrancisco',name:'旧金山',coords:[-122.4194,37.7749],job:'准备代码讲解',note:'逐步解释一次改动，并区分测试和未验状态。'},{id:'tokyo',name:'东京',coords:[139.6917,35.6895],job:'汇总阅读笔记',note:'把长篇材料压缩为可追溯的证据摘要。'}];
root.innerHTML=`<main><header><small>D3 GEO · LOCAL CONTEXT ATLAS</small><h1>让跨地域的上下文，有一个空间。</h1><p>本地地球仪示意，城市与任务是虚构协作场景，不定位、不跟踪、不连接服务。</p></header><div class="workspace"><section class="orb"><svg id="globe" viewBox="0 0 560 560" tabindex="0" role="img" aria-label="可拖动旋转的地球仪，方向键旋转"><defs><radialGradient id="ocean" cx="35%" cy="25%"><stop offset="0" stop-color="#203f46"/><stop offset="1" stop-color="#071e28"/></radialGradient><radialGradient id="halo"><stop offset="65%" stop-color="#88d0be" stop-opacity="0"/><stop offset="100%" stop-color="#88d0be" stop-opacity=".16"/></radialGradient></defs><circle cx="280" cy="280" r="250" fill="url(#halo)"/><path id="sphere" fill="url(#ocean)" stroke="#5a8b87" stroke-width="1"/><path id="grid" fill="none" stroke="#729f9d" stroke-opacity=".18" stroke-width=".7"/><path id="land" fill="#90b7a1" stroke="#133c40" stroke-width=".35"/><g id="pins"></g></svg><div class="orbit-note">拖动或方向键旋转 · 点击城市聚焦</div></section><aside><div class="city-list">${spots.map(x=>`<button data-city="${x.id}"><span>${x.name}</span><small>${x.job}</small></button>`).join('')}</div><article aria-live="polite"><small>LOCAL FIXTURE</small><h2 id="city"></h2><strong id="job"></strong><p id="note"></p><output id="coordinates"></output></article></aside></div><footer><button id="spin">开始慢转</button><button id="reset">恢复视角</button><label>缩放 <input id="scale" type="range" min="160" max="245" value="218"></label><span>Natural Earth 地形 · 无国界绘制 · 非导航地图</span></footer></main>`;
const svg=document.getElementById('globe'),land=feature(topo,topo.objects.land),graticule=geoGraticule10(),projection=geoOrthographic().translate([280,280]).scale(218).clipAngle(90),path=geoPath(projection);let rotation=[-103,-8,0],selected='singapore',drag=null,timer=null;const el=(name,attrs,text)=>{const e=document.createElementNS(NS,name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));if(text!==undefined)e.textContent=text;return e};
function draw(){projection.rotate(rotation);document.getElementById('sphere').setAttribute('d',path({type:'Sphere'}));document.getElementById('grid').setAttribute('d',path(graticule));document.getElementById('land').setAttribute('d',path(land));const pins=document.getElementById('pins');pins.replaceChildren();spots.forEach(s=>{if(geoDistance(s.coords,[-rotation[0],-rotation[1]])>Math.PI/2)return;const[x,y]=projection(s.coords),g=el('g',{'data-pin':s.id});g.append(el('circle',{cx:x,cy:y,r:selected===s.id?8:5,fill:'#f1d7a3',stroke:'#163b3a','stroke-width':2}),el('text',{x:x+12,y:y+4,fill:'#fff5dc','font-size':12},s.name));g.addEventListener('click',()=>focus(s.id));pins.append(g)})}
function focus(id){stop();selected=id;const s=spots.find(s=>s.id===id);rotation=[-s.coords[0],-s.coords[1],0];document.getElementById('city').textContent=s.name;document.getElementById('job').textContent=s.job;document.getElementById('note').textContent=s.note;document.getElementById('coordinates').textContent=`${s.coords[1].toFixed(2)}°, ${s.coords[0].toFixed(2)}° · 公开示例坐标`;document.querySelectorAll('[data-city]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.city===id)));draw()}
function stop(){if(timer!==null)clearInterval(timer);timer=null;document.getElementById('spin').textContent='开始慢转'}
document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>focus(b.dataset.city));svg.addEventListener('pointerdown',e=>{stop();drag={x:e.clientX,y:e.clientY,r:[...rotation]};svg.setPointerCapture?.(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;rotation=[drag.r[0]+(e.clientX-drag.x)*.35,Math.max(-80,Math.min(80,drag.r[1]-(e.clientY-drag.y)*.35)),0];draw()});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);svg.addEventListener('keydown',e=>{const dirs={ArrowLeft:[-7,0],ArrowRight:[7,0],ArrowUp:[0,7],ArrowDown:[0,-7]};if(!dirs[e.key])return;e.preventDefault();stop();rotation[0]+=dirs[e.key][0];rotation[1]=Math.max(-80,Math.min(80,rotation[1]+dirs[e.key][1]));draw()});document.getElementById('spin').onclick=()=>{if(timer!==null){stop();return}document.getElementById('spin').textContent='停止慢转';timer=setInterval(()=>{rotation[0]+=.4;draw()},60)};document.getElementById('reset').onclick=()=>{document.getElementById('scale').value=218;projection.scale(218);focus('singapore')};document.getElementById('scale').oninput=e=>{projection.scale(+e.target.value);draw()};const visibility=()=>{if(document.hidden)stop()};document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',()=>{stop();drag=null;document.removeEventListener('visibilitychange',visibility);root.replaceChildren()},{once:true});focus('singapore');
